insert into public.starter_recipes (title, instructions) values
  ('Crème choco', 'Mélanger le chocolat noir fondu avec le lait de soja, le sucre et la fécule de maïs. Faire épaissir à feu doux.'),
  ('Dahl lentilles', 'Faire revenir l''oignon avec le curry, ajouter les lentilles corail, le lait de coco et servir chaud avec du riz.'),
  ('Pâtes courgette curry coco', 'Cuire les pâtes. Faire poêler les courgettes avec le curry et déglacer au lait de coco.'),
  ('Gnocchis saumon', 'Poêler les gnocchis, faire saisir le saumon frais et lier le tout à la crème de soja.'),
  ('Pâtes bolognaises végé', 'Faire rissoler l''oignon et les carottes, ajouter le haché végétal et la pulpe de tomate. Servir sur les pâtes.'),
  ('Burgers végé', 'Griller le haché végétal et le pain burger. Assembler avec rondelles de tomate et fromage fondu.'),
  ('Cabillaud lait de coco', 'Pocher le filet de cabillaud dans le lait de coco parfumé au curry. Servir accompagné de riz.'),
  ('One pot chili PST', 'Mijoter les protéines de soja avec le riz, haricots rouges, maïs, pulpe de tomate, oignon rouge et paprika.'),
  ('Bagel jambon', 'Garnir le bagel avec le jambon, le fromage et des rondelles de concombre frais.'),
  ('Crêpes fromage jambon', 'Préparer la pâte avec farine, lait, œufs, huile et pincée de sucre. Garnir de jambon et fromage.'),
  ('Chakchouka', 'Faire revenir les pommes de terre et oignons au beurre, ajouter les épices et pocher les œufs par-dessus.'),
  ('Pâtes carbo', 'Faire dorér les lardons, cuire les pâtes al dente et lier le tout avec la crème de soja chaud.'),
  ('PDT et Patate douce sautées steak lentilles', 'Sauter les pommes de terre et patates douces en dés. Servir avec le steak de lentilles rissolé.'),
  ('Pâtes cheddar pulpe tomate', 'Napper les pâtes chaudes avec la sauce pulpe de tomate et faire fondre généreusement le cheddar.'),
  ('Riz soja légumes œuf', 'Sauter le riz avec poivrons, carottes, oignons, sauce soja et incorporer l''œuf brouillé.'),
  ('Salade de riz', 'Mélanger le riz froid avec dés de tomate, concombre, œufs durs et de petits dés de fromage.')
